  po r1,r2,r3,result;

  r1.set_rotate_x(rot.x);
  r2.set_rotate_y(-rot.y);
  r3.set_rotate_z(rot.z);

  result = r2*r1*r3;

  vector3d pos3;
  pos3.x = pos.x;
  pos3.y = pos.y;
  pos3.z = pos.z;
  result.set_position(pos3/12);

  get_owner()->set_rel_po(result);
}
